  return [];
}

tasks.solution:
function longTasks(values: number[], minimum: number): number[] {
  const kept: number[] = [];
  for (const value of values) {
    if (value >= minimum) kept.push(value);
  }
  return kept;
}

function emptyBins(numbers: number[]): number {
  let count = 0;
  for (const value of numbers) {
    if (value === 0) count++;
  }
  return count;
}

